package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class BigMatrixImpl_operate_TriageGen2Test {

    @Test
    public void testOperate_Success() {
        // Setup a 2x3 matrix
        // [ 1, 2, 3 ]
        // [ 4, 5, 6 ]
        BigDecimal[][] data = {
            {new BigDecimal("1"), new BigDecimal("2"), new BigDecimal("3")},
            {new BigDecimal("4"), new BigDecimal("5"), new BigDecimal("6")}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        // Vector v of length 3
        // [ 7, 8, 9 ]
        BigDecimal[] v = {
            new BigDecimal("7"),
            new BigDecimal("8"),
            new BigDecimal("9")
        };

        // Expected Calculation:
        // Row 0: (1*7) + (2*8) + (3*9) = 7 + 16 + 27 = 50
        // Row 1: (4*7) + (5*8) + (6*9) = 28 + 40 + 54 = 122
        BigDecimal[] expected = {
            new BigDecimal("50"),
            new BigDecimal("122")
        };

        BigDecimal[] result = matrix.operate(v);

        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testOperate_WrongLength_ThrowsException() {
        // Setup a 2x2 matrix
        BigMatrixImpl matrix = new BigMatrixImpl(2, 2);

        // Vector of length 3 (should be 2)
        BigDecimal[] v = {
            BigDecimal.ONE,
            BigDecimal.ONE,
            BigDecimal.ONE
        };

        try {
            matrix.operate(v);
            Assert.fail("Expected IllegalArgumentException was not thrown");
        } catch (IllegalArgumentException e) {
            Assert.assertEquals("vector has wrong length", e.getMessage());
        }
    }

    @Test
    public void testOperate_SingleElementMatrix() {
        // Setup a 1x1 matrix
        BigDecimal[][] data = {{new BigDecimal("5")}};
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        BigDecimal[] v = {new BigDecimal("10")};
        BigDecimal[] expected = {new BigDecimal("50")};

        BigDecimal[] result = matrix.operate(v);
        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testOperate_ZeroMatrix() {
        // Setup a 2x2 matrix with zeros
        BigDecimal[][] data = {
            {BigDecimal.ZERO, BigDecimal.ZERO},
            {BigDecimal.ZERO, BigDecimal.ZERO}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        BigDecimal[] v = {new BigDecimal("100"), new BigDecimal("200")};
        BigDecimal[] expected = {BigDecimal.ZERO, BigDecimal.ZERO};

        BigDecimal[] result = matrix.operate(v);
        // Note: BigDecimal.ZERO might have different scale, 
        // but the math implementation uses sum.add, so we check value equality
        Assert.assertEquals(0, expected[0].compareTo(result[0]));
        Assert.assertEquals(0, expected[1].compareTo(result[1]));
    }

    @Test
    public void testOperate_LargeValues() {
        // Testing with larger scale/precision
        BigDecimal[][] data = {
            {new BigDecimal("1.5"), new BigDecimal("2.5")}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        BigDecimal[] v = {new BigDecimal("2"), new BigDecimal("4")};
        // (1.5 * 2) + (2.5 * 4) = 3 + 10 = 13
        BigDecimal[] expected = {new BigDecimal("13.0")};

        BigDecimal[] result = matrix.operate(v);
        Assert.assertEquals(0, expected[0].compareTo(result[0]));
    }
}
